package org.jlinalg.genetics;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class VepVcfTest {
    @TempDir Path temporary;
    static final String HEADER="##fileformat=VCFv4.2\n##INFO=<ID=Z,Number=1,Type=String,Description=\"literal\">\n";
    static final String CSQ="##VEP=\"v105\"\n##INFO=<ID=CSQ,Number=.,Type=String,Description=\"Consequence annotations from Ensembl VEP. Format: Allele|Consequence|IMPACT|Gene|Feature|ALLELE_NUM|CUSTOM\">\n";
    static final String COLUMNS="#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tdonor ' α\tdonor2\n";
    static final String BEFORE="chr1\t10\tduplicate\tA\tC,G\t.\tPASS\tZ=last;A=one;F\tGT:DP:X\t0|1:.:NaN\t1/2:4:Inf\nchr1\t11\tduplicate\tC\tT\t8.0\tq10\tZ=NA\tGT:DP:X\t./.:.:.\t0/0:0:-Inf\n";
    static final String AFTER="chr1\t10\tduplicate\tA\tC,G\t.\tPASS\tA=one;F;Z=last;CSQ=C|missense_variant|MODERATE|G1|T1|1|x%3By,C|intron_variant|MODIFIER|G1|T2|1|NA,G|stop_gained|HIGH|G2|T3|2|NaN,G|missense_variant||G3|T4|2|Inf\tGT:DP:X\t0|1:.:NaN\t1/2:4:Inf\nchr1\t11\tduplicate\tC\tT\t8.0\tq10\tZ=NA;CSQ=T|intergenic_variant|MODIFIER|||1|\tGT:DP:X\t./.:.:.\t0/0:0:-Inf\n";
    static final VepVcf.Limits LIMITS=new VepVcf.Limits(1000000,100,100,8192);
    Path write(String name,String value)throws IOException{Path p=temporary.resolve(name);Files.writeString(p,value,StandardCharsets.UTF_8);return p;}
    VepVcf.Summary inspect(String value)throws IOException{return VepVcf.inspect(write("annotated.vcf",value),LIMITS,s->{},v->{},a->{},g->{});}
    @Test void completeAlleleGeneTranscriptGroupsRetainEveryLiteralToken()throws Exception{
        var annotations=new ArrayList<VepVcf.Annotation>();var variants=new ArrayList<VepVcf.Variant>();var genes=new ArrayList<VepVcf.Gene>();var summary=VepVcf.audit(write("input.vcf",HEADER+COLUMNS+BEFORE),write("output.vcf",HEADER+CSQ+COLUMNS+AFTER),LIMITS,s->assertEquals("donor ' α",s.vcfColumns().get(9)),variants::add,annotations::add,genes::add);
        assertEquals(2,summary.variants());assertEquals(5,summary.annotations());assertEquals(3,summary.geneGroups());assertEquals(1,summary.annotationsWithoutGene());assertEquals(1,summary.missingImpacts());assertEquals(1,summary.nonCsqInfoOrderChanges());assertTrue(summary.originalInputAudited());assertEquals(List.of(2,2),variants.get(0).annotationsPerAllele());assertEquals(List.of("MODERATE","HIGH"),variants.get(0).maximumObservedImpactsPerAllele());assertEquals(List.of(0,1),variants.get(0).missingImpactAnnotationsPerAllele());assertEquals("x%3By",annotations.get(0).fields().get("CUSTOM"));assertEquals("NaN",annotations.get(2).fields().get("CUSTOM"));assertEquals("",annotations.get(3).fields().get("IMPACT"));assertEquals("1/2:4:Inf",variants.get(0).fields().get(10));assertEquals(List.of("T1","T2"),genes.get(0).features());assertEquals(List.of("missense_variant","intron_variant"),genes.get(0).consequences());assertEquals("",genes.get(2).maximumOriginalImpact());assertEquals(1,genes.get(2).missingImpactAnnotations());
    }
    @Test void refusesAnyDroppedRowOrRepairedGenotype()throws Exception{Path before=write("before",HEADER+COLUMNS+BEFORE);assertThrows(IOException.class,()->VepVcf.audit(before,write("changed",HEADER+CSQ+COLUMNS+AFTER.replace("0|1:.:NaN","0/1:.:NaN")),LIMITS,s->{},v->{},a->{},g->{}));assertThrows(IOException.class,()->VepVcf.audit(before,write("dropped",HEADER+CSQ+COLUMNS+AFTER.substring(0,AFTER.indexOf("chr1\t11"))),LIMITS,s->{},v->{},a->{},g->{}));}
    @Test void ambiguousAlleleRequiresExplicitSummaryPolicy()throws Exception{String row="1\t1\t.\tA\tC,G\t.\t.\tCSQ=|missense_variant|||||\n";String text=HEADER+CSQ+"#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n"+row;assertThrows(IOException.class,()->inspect(text));var summary=VepVcf.inspect(temporary.resolve("annotated.vcf"),LIMITS,VepVcf.Policy.SOURCE_CONSEQUENCE_SUMMARY,s->{},v->assertEquals(1,v.unassignedSummaryAnnotations()),a->{assertEquals(0,a.alleleNumber());assertEquals("",a.alternate());assertEquals("",a.fields().get("IMPACT"));},g->fail("Unassigned summary cannot create an allele/gene"));assertEquals(1,summary.unassignedSummaryAnnotations());assertEquals(2,summary.unannotatedAlleles());}
    @Test void noAnnotationIsCountedWithoutInventingNoEffect()throws Exception{var summary=inspect(HEADER+CSQ+COLUMNS+BEFORE);assertEquals(0,summary.annotations());assertEquals(3,summary.unannotatedAlleles());}
    @Test void duplicateAnnotationsAndMultitermConsequencesAreRetained()throws Exception{String duplicate="C|intron_variant|MODIFIER|G1|T2|1|NA";String altered=AFTER.replace("missense_variant|MODERATE|G1","missense_variant&splice_region_variant|MODERATE|G1").replace(duplicate,duplicate+","+duplicate);var genes=new ArrayList<VepVcf.Gene>();var summary=VepVcf.inspect(write("multi",HEADER+CSQ+COLUMNS+altered),LIMITS,s->{},v->{},a->{},genes::add);assertEquals(6,summary.annotations());assertEquals(3,genes.get(0).annotations());assertEquals(List.of("T1","T2"),genes.get(0).features());assertEquals(List.of("missense_variant","splice_region_variant","intron_variant"),genes.get(0).consequences());}
    @Test void refusesMalformedSchemasAndInfoRatherThanGuessing()throws Exception{assertThrows(IOException.class,()->inspect(HEADER+CSQ.replace("ALLELE_NUM","UNKNOWN")+COLUMNS+AFTER));assertThrows(IOException.class,()->inspect(HEADER+CSQ+COLUMNS+AFTER.replace("Z=NA;CSQ=","Z=NA;Z=again;CSQ=")));assertThrows(IOException.class,()->inspect(HEADER+CSQ+COLUMNS.replace("\tINFO\t","\tINFOjunk\t")+AFTER));}
    @Test void refusesMissingFieldInvalidImpactAndOutOfRangeAllele()throws Exception{assertThrows(IOException.class,()->inspect(HEADER+CSQ+COLUMNS+AFTER.replace("MODERATE","BENIGN")));assertThrows(IOException.class,()->inspect(HEADER+CSQ+COLUMNS+AFTER.replace("|T3|2|","|T3|3|")));assertThrows(IOException.class,()->inspect(HEADER+CSQ+COLUMNS+AFTER.replace("|1|x%3By","|1")));}
    @Test void annotationAndDecodedCapacitiesDoNotReturnPartialSuccess()throws Exception{Path p=write("a",HEADER+CSQ+COLUMNS+AFTER);assertThrows(IOException.class,()->VepVcf.inspect(p,new VepVcf.Limits(1000000,100,4,8192),s->{},v->{},a->{},g->{}));assertThrows(IOException.class,()->VepVcf.inspect(p,new VepVcf.Limits(20,100,100,8192),s->{},v->{},a->{},g->{}));assertThrows(IOException.class,()->VepVcf.inspect(p,new VepVcf.Limits(1000000,1,100,8192),s->{},v->{},a->{},g->{}));}
    @Test void invalidUtf8AndTruncatedGzipFail()throws Exception{Path p=temporary.resolve("bad");Files.write(p,new byte[]{(byte)0xc3,0x28});assertThrows(IOException.class,()->VepVcf.inspect(p,LIMITS,s->{},v->{},a->{},g->{}));ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(var out=new GZIPOutputStream(bytes)){out.write((HEADER+CSQ+COLUMNS+AFTER).getBytes(StandardCharsets.UTF_8));}Files.write(p,Arrays.copyOf(bytes.toByteArray(),bytes.size()-4));assertThrows(IOException.class,()->VepVcf.inspect(p,LIMITS,s->{},v->{},a->{},g->{}));}
    @Test void gzipAllRowsAndOriginalUnicodeArePreserved()throws Exception{Path p=temporary.resolve("data.gz");try(var out=new GZIPOutputStream(Files.newOutputStream(p))){out.write((HEADER+CSQ+COLUMNS+AFTER).getBytes(StandardCharsets.UTF_8));}assertEquals(5,VepVcf.inspect(p,LIMITS,s->{},v->{},a->{},g->{}).annotations());}
    @Test void refusesPreexistingInputCsqInsteadOfOverwriting()throws Exception{assertThrows(IOException.class,()->VepVcf.inspectOriginal(write("before",HEADER+CSQ+COLUMNS+AFTER),LIMITS,v->{}));}
    @Test void rankTiesDoNotImplySameImpactOrPickOneTranscript(){assertEquals(40,VepConsequences105.terms().size());assertEquals(List.of("splice_donor_5th_base_variant","stop_gained"),VepConsequences105.minimumRankTerms(List.of("intron_variant","splice_donor_5th_base_variant","stop_gained","stop_gained")));assertEquals(Optional.of(VepConsequences105.Impact.HIGH),VepConsequences105.maximumImpact(List.of("splice_donor_5th_base_variant","stop_gained")));assertEquals(Optional.empty(),VepConsequences105.maximumImpact(List.of()));assertThrows(IllegalArgumentException.class,()->VepConsequences105.consequence("future_unknown_term"));assertThrows(UnsupportedOperationException.class,()->VepConsequences105.terms().clear());}
}
